// Inventory, Payment, Shipping subsystems
class Inventory { reserve(itemId: string) { /*...*/ } }
class PaymentGateway { process(amount: number) { /*...*/ } }
class Shipping { schedule(orderId: string) { /*...*/ } }
class OrderFacade {
  constructor(private inv: Inventory, private pay: PaymentGateway, private ship: Shipping) {}
  placeOrder(order: any) { this.inv.reserve(order.item); this.pay.process(order.total); this.ship.schedule(order.id); }
}
const facade = new OrderFacade(new Inventory(), new PaymentGateway(), new Shipping());
facade.placeOrder({ id: 'o1', item: 'sku1', total: 199 });

class BillingFacade {
  constructor(private gateway: PaymentGateway) {}
  charge(order: Order): PaymentResult { return this.gateway.processPayment(order.total); }
  refund(txId: string): PaymentResult { return this.gateway.refund(txId); }
}
